// Node.js example: verify the signature before parsing the body
const crypto = require('node:crypto');
function verify(rawBody, headers, secret) {
  const ts = headers['x-upaynow-timestamp'];
  if (Math.abs(Date.now() / 1000 - Number(ts)) > 300) return false;   // Time window
  const expected = crypto.createHmac('sha256', secret).update(ts + '.' + rawBody).digest('hex');
  const given = String(headers['x-upaynow-signature'] || '');
  return given.length === expected.length && crypto.timingSafeEqual(Buffer.from(given), Buffer.from(expected));
}
